    35→/**
    36→ * Parse agent markdown file
    37→ */
    38→export function parseAgentFile(filePath: string): AgentDefinition | null {
    39→  if (!existsSync(filePath)) {
    40→    return null;
    41→  }
    42→
    43→  try {
    44→    const content = readFileSync(filePath, 'utf-8');
    45→    const { data, content: body } = matter(content);
    46→    const frontmatter = data as AgentFrontmatter;
    47→
    48→    // Extract sections from markdown body
    49→    const sections = parseMarkdownSections(body);
    50→
    51→    // Build trigger configuration
    52→    const triggers: AgentTrigger = {
    53→      keywords: frontmatter.triggers?.keywords ?? [],
    54→      patterns: frontmatter.triggers?.patterns?.map(p => new RegExp(p, 'i')),
    55→      fileExtensions: frontmatter.triggers?.fileExtensions,
    56→      priority: frontmatter.triggers?.priority ?? 1,
    57→    };
    58→
    59→    // Build capabilities
    60→    const capabilities: AgentCapability[] = frontmatter.capabilities ?? [];
    61→
    62→    // Build agent definition
    63→    const agent: AgentDefinition = {
    64→      id: frontmatter.id,
    65→      name: frontmatter.name,
    66→      version: frontmatter.version ?? '1.0.0',
    67→      domain: frontmatter.domain as AgentDomain,
    68→      tier: frontmatter.tier as AgentTier | undefined,
    69→      description: frontmatter.description,
    70→      defaultModel: frontmatter.defaultModel,
    71→      preferredModels: frontmatter.preferredModels,
    72→      minTier: frontmatter.minTier as AgentDefinition['minTier'],
    73→      capabilities,
    74→      tools: frontmatter.tools,
    75→      mcpServers: frontmatter.mcpServers,
    76→      triggers,
    77→      systemPrompt: sections.systemPrompt ?? body,
    78→      instructions: sections.instructions,
    79→      constraints: sections.constraints,
    80→      collaboratesWith: frontmatter.collaboratesWith,
    81→      delegatesTo: frontmatter.delegatesTo,
    82→      author: frontmatter.author,
    83→      tags: frontmatter.tags,
    84→      sourcePath: filePath,
    85→    };
    86→
    87→    return agent;
    88→  } catch (error) {
    89→    console.error(`Error parsing agent file ${filePath}:`, error);
    90→    return null;
    91→  }
    92→}
