    94→/**
    95→ * Parse markdown sections
    96→ */
    97→function parseMarkdownSections(content: string): {
    98→  systemPrompt?: string;
    99→  instructions?: string[];
   100→  constraints?: string[];
   101→} {
   102→  const sections: ReturnType<typeof parseMarkdownSections> = {};
   103→
   104→  // Find system prompt section
   105→  const systemPromptMatch = content.match(/##\s*System\s*Prompt\s*\n([\s\S]*?)(?=\n##|$)/i);
   106→  if (systemPromptMatch) {
   107→    sections.systemPrompt = systemPromptMatch[1].trim();
   108→  } else {
   109→    // Use entire content as system prompt if no section headers
   110→    sections.systemPrompt = content.trim();
   111→  }
   112→
   113→  // Find instructions section
   114→  const instructionsMatch = content.match(/##\s*Instructions\s*\n([\s\S]*?)(?=\n##|$)/i);
   115→  if (instructionsMatch) {
   116→    sections.instructions = parseListItems(instructionsMatch[1]);
   117→  }
   118→
   119→  // Find constraints section
   120→  const constraintsMatch = content.match(/##\s*Constraints\s*\n([\s\S]*?)(?=\n##|$)/i);
   121→  if (constraintsMatch) {
   122→    sections.constraints = parseListItems(constraintsMatch[1]);
   123→  }
   124→
   125→  return sections;
   126→}
   127→
   128→/**
   129→ * Parse markdown list items
   130→ */
   131→function parseListItems(content: string): string[] {
   132→  const items: string[] = [];
   133→  const lines = content.split('\n');
   134→
   135→  for (const line of lines) {
   136→    const match = line.match(/^\s*[-*]\s+(.+)$/);
   137→    if (match) {
   138→      items.push(match[1].trim());
   139→    }
   140→  }
   141→
   142→  return items;
   143→}
