   145→/**
   146→ * Load all agents from a directory
   147→ */
   148→export function loadAgentsFromDirectory(dirPath: string): AgentDefinition[] {
   149→  if (!existsSync(dirPath)) {
   150→    return [];
   151→  }
   152→
   153→  const agents: AgentDefinition[] = [];
   154→
   155→  function scanDir(dir: string): void {
   156→    const entries = readdirSync(dir);
   157→
   158→    for (const entry of entries) {
   159→      const fullPath = join(dir, entry);
   160→      const stat = statSync(fullPath);
   161→
   162→      if (stat.isDirectory()) {
   163→        scanDir(fullPath);
   164→      } else if (entry.endsWith('.md')) {
   165→        const agent = parseAgentFile(fullPath);
   166→        if (agent) {
   167→          agents.push(agent);
   168→        }
   169→      }
   170→    }
   171→  }
   172→
   173→  scanDir(dirPath);
   174→  return agents;
   175→}
