    19→
    20→  /**
    21→   * Load agents from built-in and custom directories
    22→   */
    23→  load(config: OmcConfig): void {
    24→    const agentsConfig = config.agents ?? { enabled: true };
    25→
    26→    if (!agentsConfig.enabled) {
    27→      return;
    28→    }
    29→
    30→    // Load built-in agents
    31→    const builtInPath = getBuiltInAgentsPath();
    32→    const builtInAgents = loadAgentsFromDirectory(builtInPath);
    33→
    34→    for (const agent of builtInAgents) {
    35→      this.register(agent);
    36→    }
    37→
    38→    // Load custom agents if path specified
    39→    if (agentsConfig.customPath) {
    40→      const customAgents = loadAgentsFromDirectory(agentsConfig.customPath);
    41→      for (const agent of customAgents) {
    42→        this.register(agent);
    43→      }
    44→    }
    45→
    46→    // Remove disabled agents
    47→    if (agentsConfig.disabled) {
    48→      for (const id of agentsConfig.disabled) {
    49→        this.agents.delete(id);
    50→      }
    51→      this.rebuildIndexes();
    52→    }
    53→  }
    54→
    55→  /**
    56→   * Register a single agent
    57→   */
    58→  register(agent: AgentDefinition): void {
    59→    this.agents.set(agent.id, agent);
    60→
    61→    // Index by domain
    62→    const domainList = this.byDomain.get(agent.domain) ?? [];
    63→    domainList.push(agent);
    64→    this.byDomain.set(agent.domain, domainList);
    65→
    66→    // Index by tier
    67→    if (agent.tier) {
    68→      const tierList = this.byTier.get(agent.tier) ?? [];
    69→      tierList.push(agent);
    70→      this.byTier.set(agent.tier, tierList);
    71→    }
    72→  }
    73→
    74→  /**
    75→   * Rebuild domain and tier indexes
    76→   */
    77→  private rebuildIndexes(): void {
    78→    this.byDomain.clear();
    79→    this.byTier.clear();
    80→
    81→    for (const agent of this.agents.values()) {
    82→      const domainList = this.byDomain.get(agent.domain) ?? [];
    83→      domainList.push(agent);
    84→      this.byDomain.set(agent.domain, domainList);
    85→
    86→      if (agent.tier) {
    87→        const tierList = this.byTier.get(agent.tier) ?? [];
    88→        tierList.push(agent);
    89→        this.byTier.set(agent.tier, tierList);
